package com.oldschoolnetwork.store.lite;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import com.oldschoolnetwork.lite.Api;import org.json.*;
final class ReportDialog {
 static void show(final Activity activity,final String kind,final int id){
  if(Api.account(activity)==null){Api.signIn(activity);return;}View fields=activity.getLayoutInflater().inflate(R.layout.report,null);final Spinner reason=(Spinner)fields.findViewById(R.id.reason);final EditText details=(EditText)fields.findViewById(R.id.details);final TextView status=(TextView)fields.findViewById(R.id.status);final String[] reasons={"Inappropriate content","Spam or misleading","Malware or virus","Harassment","Other"};reason.setAdapter(new ArrayAdapter<String>(activity,android.R.layout.simple_spinner_dropdown_item,reasons));
  final AlertDialog dialog=new AlertDialog.Builder(activity).setTitle("Report "+kind).setView(fields).setPositiveButton("Send",null).setNegativeButton("Close",null).create();dialog.show();final Button send=dialog.getButton(DialogInterface.BUTTON_POSITIVE);send.setEnabled(false);
  JSONObject target=new JSONObject();try{target.put("target_type",kind).put("target_id",id);}catch(Exception ignored){}
  Api.call(activity,"store_report_status",target,true,new Api.Callback(){public void complete(JSONObject r,String error){if(!dialog.isShowing())return;if(error!=null){status.setText(error);return;}JSONObject old=r.optJSONObject("report");boolean editable=old==null||old.optBoolean("editable");send.setEnabled(editable);details.setEnabled(editable);reason.setEnabled(editable);if(old!=null){for(int i=0;i<reasons.length;i++)if(reasons[i].equals(old.optString("reason")))reason.setSelection(i);details.setText(old.optString("details"));send.setText("Update report");}status.setText(old==null?"Additional details are optional.":editable?"Pending report. You can edit it.":"This report has already been reviewed.");}});
  send.setOnClickListener(new View.OnClickListener(){public void onClick(View v){JSONObject body=new JSONObject();try{body.put("target_type",kind).put("target_id",id).put("reason",reason.getSelectedItem().toString()).put("details",details.getText().toString());}catch(Exception ignored){}send.setEnabled(false);Api.call(activity,"platform_report",body,true,new Api.Callback(){public void complete(JSONObject r,String error){if(!dialog.isShowing())return;if(error!=null){status.setText(error);send.setEnabled(true);}else dialog.dismiss();}});}});
 }
}
